import{_ as r,l as s,o as e,c as l,v as t,p as n,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"信号","description":"","frontmatter":{"title":"信号","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/signals.md","filePath":"cs/signals.md","lastUpdated":1789023840000}'),h={name:"cs/signals.md"};function E(m,a,_,P,B,u){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="信号" tabindex="-1">信号 <a class="header-anchor" href="#信号" aria-label="Permalink to &quot;信号&quot;">​</a></h1><div class="epigraph"><p>信号是通知进程某事件已发生的软件中断；进程可以忽略、捕获或取默认动作。</p><footer>—— 据 Stevens and Rago, Advanced Programming in the UNIX Environment；POSIX 对 signal 的整理</footer></div><p><a href="/cs/iommu">上一课</a>把期限任务与分时对照完毕。设备 IRQ 走内核下半部；用户线程还缺一种<strong>针对自己的异步通知</strong>：子进程退出、终端键、闹钟、非法内存。缺口不是再调度一次，而是内核向进程投递一种编号事件——信号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若父进程只能 <code>wait</code> 轮询，子进程退出的消息会迟到。若用管道专门传「你被中断了」，每个事件都要先建立通道。Unix 把一小类事件做成信号：内核置位，在该进程回到用户态的边界递送。缺口是：执行流在指令边界被拽去处理程序，再回来——像中断，但对象是进程，不是 CPU 向量。</p><p>本课不把实时信号排队语义写全，也不把 <code>sigaction</code> 的全部标志背完。</p><p><span class="marginnote">默认动作可以是终止、核心转储、停止或忽略。<code>SIGKILL</code> 与 <code>SIGSTOP</code> 不能捕获，以免进程拒绝被内核回收。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内核在 PCB 里记 pending 与 blocked 集合。递送点通常是从内核返回用户之前：若有未阻塞信号，改用户 PC 指向处理函数，并安排返回时回到原指令。处理函数在用户态跑，仍受页表与特权限制；它要再请内核，还走<a href="/cs/syscall-path">系统调用路径</a>。</p>',9)),(e(),n(p,null,{default:o(()=>[c(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVT%5B%22%E5%86%85%E6%A0%B8%E4%BA%8B%E4%BB%B6%E6%88%96%20kill%22%5D%20--%3E%20PEND%5B%22%E8%BF%9B%E7%A8%8B%20pending%22%5D%0A%20%20PEND%20--%3E%20RET%5B%22%E8%BF%94%E5%9B%9E%E7%94%A8%E6%88%B7%E5%89%8D%E6%A3%80%E6%9F%A5%22%5D%0A%20%20RET%20--%3E%20HND%5B%22%E7%94%A8%E6%88%B7%E5%A4%84%E7%90%86%E5%87%BD%E6%95%B0%22%5D%0A%20%20HND%20--%3E%20OLD%5B%22%E5%9B%9E%E5%88%B0%E5%8E%9F%20PC%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>进程间也可以 <code>kill</code> 投递，这是一种极窄的 IPC，几乎不携带数据。真正传字节是下一课管道。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信号把「异步」从设备扩到软件：闹钟到期、管道对端关闭、窗口大小变化，都可以在线程不知情的指令间隙插入。与<a href="/cs/interrupt-bottom-half">中断下半部</a>的分工：硬件 IRQ 先在内核消化；只有需要该用户进程知情时才置信号。调度仍然决定进程何时跑；信号不代替调度器。</p><p>可重入问题：处理函数里调用不可重入库，会与主控制流抢同一用户锁。本课只点名，互斥是后课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Windows APC 或 Mach 消息当成同一课对象。不讲信号在多线程里精确递送到哪条线程的全部 POSIX 规则，只承认：信号是进程级事件，线程可以有掩码。也不把信号当通用 RPC。</p><p>后课默认：进程可以被编号事件打断。要传的是字节流而不是一位事件，下一课用管道与 IPC。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>信号是指向进程的软件中断，在回用户态时递送。</li><li>几乎不带数据；默认动作由内核规定。</li><li>字节级通信是管道的缺口。</li><li>出处：Stevens and Rago, <em>APUE</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',9))])}const g=r(h,[["render",E]]);export{A as __pageData,g as default};
